    "agentes.py":{name:"agents.py",src:`# daily routine of the funding calls hub
from agents import Scout, Extractor
from agents import Assessor, Monitor

def daily_routine(db):
    calls = Scout().search()
    for call in calls:
        data = Extractor().read(call)
        score = Assessor().assess(data)
        # AI assesses, but priority is human
        db.save(data, score, status="New",
                priority=None)
    Monitor().watch_deadlines(db)`},
