    "agentes.py":{src:`# rutina diaria de la central de convocatorias
from agentes import Buscador, Extractor
from agentes import Evaluador, Monitor

def rutina_diaria(base):
    convocatorias = Buscador().buscar()
    for conv in convocatorias:
        datos = Extractor().leer(conv)
        nota = Evaluador().evaluar(datos)
        # la IA evalúa, pero la prioridad es humana
        base.guardar(datos, nota, estado="Nuevo",
                     prioridad=None)
    Monitor().vigilar_plazos(base)`},
